// ❌ OLD: window.resize only fires when the VIEWPORT changes — it
// misses element-level size changes (flex/grid layout shifts, content
// growth, container queries without CQ) and reads offsetWidth, which
// forces a synchronous layout.
window.addEventListener('resize', () => {
  // ❌ OLD: manual measurement on every window resize
  const w = el.offsetWidth; // forces layout read
  render(w);
});

// If the element resizes because its content or CSS changes but the
// window doesn't move, this handler never fires — layout stays stale.
// Also requires manual cleanup and re-measure on font-load/DOM change.

// ✅ NEW: ResizeObserver watches the element itself, delivers entries
// after layout settles, and batches multiple changes into one callback.
const ro = new ResizeObserver((entries) => {
  for (const entry of entries) {
    const w = entry.contentRect.width; // ✅ NEW: content-box geometry
    render(w);
  }
});

ro.observe(el); // ✅ NEW: fires for ANY size change of el, not just window

// Catches flex/grid-driven resizes, container changes, and content
// growth. Call ro.disconnect() in cleanup to stop observing.
